// This file is generated by AI.

// 视频导出编译期警告的展示逻辑（纯函数，可直接单测）。
//
// 后端在开始渲染前推 `video-export:warnings`，内容是 `plan.warnings`：某条语句或某个
// 动画在离线导出里不会完全生效（例如 v2 动画格式、退场动画的位移、pixiPerform 粒子）。
// 这些不是错误，导出会继续，所以单独一栏用警示色展示。

import type { VideoExportWarning } from '../commands/videoExport';

/** `场景:行号` 形式的定位；缺字段时退化成能给出的部分。 */
export function warningLocation(warning: VideoExportWarning): string {
  const scene = warning.scene?.trim() ?? '';
  const line = typeof warning.line === 'number' && warning.line > 0 ? warning.line : 0;
  if (scene && line > 0) return `${scene}:${line}`;
  if (scene) return scene;
  if (line > 0) return `第 ${line} 行`;
  return '';
}

/**
 * 列表展示用的切片：同一条警告（码+文案+位置完全相同）只留一份，
 * 最多展示 `limit` 条，其余用计数提示。`total` 是去重后的条数，
 * 因此恒有 `shown.length + hidden === total`。
 */
export function summarizeWarnings(
  warnings: readonly VideoExportWarning[],
  limit = 5
): { total: number; shown: VideoExportWarning[]; hidden: number } {
  const seen = new Set<string>();
  const unique: VideoExportWarning[] = [];
  for (const warning of warnings) {
    const key = [warning.code, warning.message, warning.scene ?? '', warning.line ?? 0].join('\u0000');
    if (seen.has(key)) continue;
    seen.add(key);
    unique.push(warning);
  }
  const bound = Math.max(1, Math.trunc(limit));
  return {
    total: unique.length,
    shown: unique.slice(0, bound),
    hidden: Math.max(0, unique.length - bound),
  };
}
